cat > recheck.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ channel: 'chrome', headless: true });
for (const [scheme, theme] of [['dark', 'light'], ['light', 'dark']]) {
  const context = await browser.newContext({ colorScheme: scheme, viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  await page.goto('http://localhost:4173/');
  await page.evaluate((t) => document.documentElement.setAttribute('data-theme', t), theme);
  await page.waitForTimeout(600);
  const btn = await page.locator('button[type="submit"]').evaluate((el) => getComputedStyle(el).backgroundColor);
  await page.getByRole('combobox', { name: 'Category' }).focus();
  await page.keyboard.press('Enter');
  const lb = page.getByRole('listbox');
  await lb.waitFor();
  await page.waitForTimeout(400);
  const chain = await lb.evaluate((el) => { const r = []; let n = el; for (let i = 0; i < 4 && n; i++, n = n.parentElement) r.push([n.tagName, getComputedStyle(n).backgroundColor, getComputedStyle(n).colorScheme]); return r; });
  console.log(scheme, '->', theme, 'button', btn, 'popup chain', JSON.stringify(chain));
  await page.screenshot({ path: `shot-popup-${theme}.png` });
  await context.close();
}
await browser.close();
EOF
